@dataclass(frozen=True)
class Style:
    color: Optional[str] = None
    bold: bool = False


PLAIN = Style()
BOLD = Style(bold=True)
BLUE = Style(color="94")
GREEN = Style(color="92")
CYAN = Style(color="96")
YELLOW = Style(color="93")
RED = Style(color="91")
GRAY = Style(color="90")


@dataclass
class Segment:
    text: str
    style: Style = PLAIN
    focus_id: Optional[tuple] = None


@dataclass
class View:
    lines: list[list[Segment]]
    focus_order: list[tuple]
    table_shapes: dict[tuple, tuple[int, int]]
    selected_line: int


class JsonParseError(Exception):
    def __init__(self, line: int, column: int, detail: str) -> None:
        self.line = line
        self.column = column
        self.detail = detail

    def __str__(self) -> str:
        return (
            "[json.exception.parse_error.101] parse error at "
            f"line {self.line}, column {self.column}: {self.detail}"
        )


class JsonParser:
    def __init__(self, text: str) -> None:
        self.text = text
        self.index = 0
        self.line = 1
        self.column = 1

    def parse(self) -> Any:
        self.skip_ws()
        if self.eof():
            raise JsonParseError(
                1,
                1,
                "attempting to parse an empty input; check that your input string "
                "or stream contains the expected JSON",
            )
        value = self.parse_value()
        self.skip_ws()
        if not self.eof():
            self.raise_unexpected(
                "value",
                self.describe_token(),
                "end of input",
            )
        return value

    def eof(self) -> bool:
        return self.index >= len(self.text)

    def current(self) -> str:
        return "" if self.eof() else self.text[self.index]

    def advance(self) -> str:
        char = self.text[self.index]
        self.index += 1
        if char == "\n":
            self.line += 1
            self.column = 1
        else:
            self.column += 1
        return char

    def skip_ws(self) -> None:
        while not self.eof() and self.current() in " \t\r\n":
            self.advance()

    def raise_unexpected(self, context: str, unexpected: str, expected: str) -> None:
        raise JsonParseError(
            self.line,
            self.column,
            f"syntax error while parsing {context} - unexpected {unexpected}; expected {expected}",
        )

    def describe_token(self) -> str:
        if self.eof():
            return "end of input"
        char = self.current()
        if char == '"':
            return "string literal"
        if char in "-0123456789":
            return "number literal"
        if char in "[{}]":
            return f"'{char}'"
        if char.isalpha():
            return "literal"
        return f"'{char}'"

    def parse_value(self) -> Any:
        self.skip_ws()
        if self.eof():
            self.raise_unexpected("value", "end of input", "'[', '{', or a literal")
        char = self.current()
        if char == "{":
            return self.parse_object()
        if char == "[":
            return self.parse_array()
        if char == '"':
            return self.parse_string()
        if char == "t":
            return self.parse_literal("true", True)
        if char == "f":
            return self.parse_literal("false", False)
        if char == "n":
            return self.parse_literal("null", None)
        if char in "-0123456789":
            return self.parse_number()
        if char.isalpha():
            start = self.index
            while not self.eof() and self.current().isalpha():
                self.advance()
            snippet = self.text[start:self.index]
            raise JsonParseError(
                self.line,
                self.column,
                f"syntax error while parsing value - invalid literal; last read: '{snippet}'",
            )
        self.raise_unexpected("value", self.describe_token(), "'[', '{', or a literal")
        raise AssertionError("unreachable")

    def parse_literal(self, literal: str, value: Any) -> Any:
        start = self.index
        matched = 0
        while matched < len(literal) and not self.eof() and self.current() == literal[matched]:
            self.advance()
            matched += 1
        if matched == len(literal):
            return value
        while not self.eof() and self.current().isalpha():
            self.advance()
        snippet = self.text[start:self.index]
        raise JsonParseError(
            self.line,
            self.column,
            f"syntax error while parsing value - invalid literal; last read: '{snippet}'",
        )

    def parse_number(self) -> Any:
        start = self.index
        if self.current() == "-":
            self.advance()
        if self.eof():
            snippet = self.text[start:self.index]
            raise JsonParseError(
                self.line,
                self.column,
                f"syntax error while parsing value - invalid number; last read: '{snippet}'",
            )
        if self.current() == "0":
            self.advance()
        elif self.current() in "123456789":
            while not self.eof() and self.current().isdigit():
                self.advance()
        else:
            self.raise_unexpected("value", self.describe_token(), "'[', '{', or a literal")
        if not self.eof() and self.current() == ".":
            self.advance()
            if self.eof() or not self.current().isdigit():
                snippet = self.text[start:self.index]
                raise JsonParseError(
                    self.line,
                    self.column,
                    f"syntax error while parsing value - invalid number; last read: '{snippet}'",
                )
            while not self.eof() and self.current().isdigit():
                self.advance()
        if not self.eof() and self.current() in "eE":
            self.advance()
            if not self.eof() and self.current() in "+-":
                self.advance()
            if self.eof() or not self.current().isdigit():
                snippet = self.text[start:self.index]
                raise JsonParseError(
                    self.line,
                    self.column,
                    f"syntax error while parsing value - invalid number; last read: '{snippet}'",
                )
            while not self.eof() and self.current().isdigit():
                self.advance()
        token = self.text[start:self.index]
        if "." in token or "e" in token or "E" in token:
            return float(token)
        return int(token)

    def parse_string(self) -> str:
        if self.current() != '"':
            self.raise_unexpected("string", self.describe_token(), "'\"'")
        self.advance()
        chars: list[str] = []
        while not self.eof():
            char = self.current()
            if char == '"':
                self.advance()
                return "".join(chars)
            if char == "\\":
                self.advance()
                if self.eof():
                    self.raise_unexpected("string", "end of input", "escape sequence")
                escape = self.current()
                mapping = {
                    '"': '"',
                    "\\": "\\",
                    "/": "/",
                    "b": "\b",
                    "f": "\f",
                    "n": "\n",
                    "r": "\r",
                    "t": "\t",
                }
                if escape in mapping:
                    chars.append(mapping[escape])
                    self.advance()
                    continue
                if escape == "u":
                    self.advance()
                    digits = []
                    for _ in range(4):
                        if self.eof() or self.current() not in "0123456789abcdefABCDEF":
                            self.raise_unexpected("string", self.describe_token(), "hex digit")
                        digits.append(self.current())
                        self.advance()
                    chars.append(chr(int("".join(digits), 16)))
                    continue
                self.raise_unexpected("string", f"'{escape}'", "valid escape sequence")
            if ord(char) < 0x20:
                self.raise_unexpected("string", f"'{char}'", "valid string character")
            chars.append(char)
            self.advance()
        self.raise_unexpected("string", "end of input", "'\"'")
        raise AssertionError("unreachable")

    def parse_object(self) -> dict[str, Any]:
        obj: dict[str, Any] = {}
        self.advance()
        self.skip_ws()
        if self.eof():
            self.raise_unexpected("object key", "end of input", "string literal")
        if self.current() == "}":
            self.advance()
            return obj
        while True:
            self.skip_ws()
            if self.eof():
                self.raise_unexpected("object key", "end of input", "string literal")
            if self.current() != '"':
                if self.current().isalpha():
                    token_start = max(0, self.index - 1)
                    while not self.eof() and self.current().isalpha():
                        self.advance()
                    snippet = self.text[token_start:self.index]
                    raise JsonParseError(
                        self.line,
                        self.column,
                        "syntax error while parsing object key - "
                        f"invalid literal; last read: '{snippet}'; expected string literal",
                    )
                self.raise_unexpected("object key", self.describe_token(), "string literal")
            key = self.parse_string()
            self.skip_ws()
            if self.eof():
                self.raise_unexpected("object separator", "end of input", "':'")
            if self.current() != ":":
                self.raise_unexpected("object separator", self.describe_token(), "':'")
            self.advance()
            obj[key] = self.parse_value()
            self.skip_ws()
            if self.eof():
                self.raise_unexpected("object", "end of input", "'}'")
            if self.current() == "}":
                self.advance()
                return obj
            if self.current() == ",":
                self.advance()
                self.skip_ws()
                if self.eof():
                    self.raise_unexpected("object key", "end of input", "string literal")
                continue
            self.raise_unexpected("object", self.describe_token(), "'}'")

    def parse_array(self) -> list[Any]:
        array: list[Any] = []
        self.advance()
        self.skip_ws()
        if self.eof():
            self.raise_unexpected("value", "end of input", "'[', '{', or a literal")
        if self.current() == "]":
            self.advance()
            return array
        while True:
            array.append(self.parse_value())
            self.skip_ws()
            if self.eof():
                self.raise_unexpected("array", "end of input", "']'")
            if self.current() == "]":
                self.advance()
                return array
            if self.current() == ",":
                self.advance()
                self.skip_ws()
                if self.eof():
                    self.raise_unexpected("value", "end of input", "'[', '{', or a literal")
                continue
            self.raise_unexpected("array", self.describe_token(), "']'")


def is_container(value: Any) -> bool:
    return isinstance(value, (dict, list))


def is_eligible_table(value: Any) -> bool:
    return isinstance(value, list) and value and all(isinstance(item, dict) for item in value)


def json_string(text: str) -> str:
    escaped = text.translate(
        str.maketrans(
            {
                "\\": "\\\\",
                '"': '\\"',
                "\b": "\\b",
                "\f": "\\f",
                "\n": "\\n",
                "\r": "\\r",
                "\t": "\\t",
            }
        )
    )
    return f'"{escaped}"'


def format_value(value: Any) -> str:
    if value is None:
        return "null"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, str):
        return json_string(value)
    if isinstance(value, float):
        return repr(value)
    return str(value)


def primitive_style(value: Any) -> Style:
    if value is None:
        return RED
    if isinstance(value, bool):
        return YELLOW
    if isinstance(value, str):
        return GREEN
    return CYAN


def summarize(value: Any) -> tuple[str, Style]:
    if isinstance(value, dict):
        return "{...}", BOLD
    if isinstance(value, list):
        return "[...]", BOLD
    return format_value(value), primitive_style(value)


def style_prefix(style: Style, selected: bool) -> str:
    parts: list[str] = []
    if selected:
        parts.append("\x1b[7m")
    if style.bold and not selected:
        parts.append("\x1b[1m")
    if style.color is not None:
        parts.append(f"\x1b[{style.color}m\x1b[49m")
    return "".join(parts)


def style_suffix(style: Style, selected: bool) -> str:
    parts: list[str] = []
    if selected:
        parts.append("\x1b[27m")
    if style.bold and not selected:
        parts.append("\x1b[22m")
    if style.color is not None:
        parts.append("\x1b[39m\x1b[49m")
    return "".join(parts)


class App:
    def __init__(self, data: Any, fullscreen: bool) -> None:
        self.data = data
        self.fullscreen = fullscreen
        self.expanded: set[tuple] = set()
        self.table_paths: set[tuple] = set()
        self._seed_expanded(self.data, (), 0)
        self.selected_focus: tuple = ("tree", ())
        self.scroll = 0
        self.pending_g = False
        self.view = View([], [], {}, 0)
        self.saved_cursor = False

    def _seed_expanded(self, node: Any, path: tuple, depth: int) -> None:
        if depth == 0 and is_container(node):
            self.expanded.add(path)
        if depth == 1 and isinstance(node, dict):
            self.expanded.add(path)
        if depth >= 1:
            return
        if isinstance(node, dict):
            for key, child in node.items():
                self._seed_expanded(child, path + (key,), depth + 1)
        elif isinstance(node, list):
            for index, child in enumerate(node):
                self._seed_expanded(child, path + (index,), depth + 1)

    def run(self) -> int:
        input_fd, should_close = self._open_input_fd()
        if not sys.stdout.isatty() or input_fd is None:
            snapshot = self._render_plain_snapshot(80)
            if snapshot:
                sys.stdout.write(snapshot)
            return 0

        old_settings = termios.tcgetattr(input_fd)
        try:
            tty.setraw(input_fd)
            out = sys.stdout
            if self.fullscreen:
                out.write("\x1b[?1049h")
            else:
                out.write("\r\x1b[2K")
            out.write("\x1b[?7l\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x1b[?25l")
            out.flush()

            while True:
                self._render_terminal()
                key = self._read_key(input_fd)
                if key is None:
                    continue
                if self._handle_key(key):
                    break
            out.write("\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l\x1b[?7h\x1b[?25h")
            if self.fullscreen:
                out.write("\x1b[?1049l")
            out.write("\x1b[1 q\r\n")
            out.flush()
            return 0
        finally:
            termios.tcsetattr(input_fd, termios.TCSADRAIN, old_settings)
            if should_close:
                os.close(input_fd)

    def _open_input_fd(self) -> tuple[Optional[int], bool]:
        try:
            return os.open("/dev/tty", os.O_RDONLY), True
        except OSError:
            if sys.stdin.isatty():
                return sys.stdin.fileno(), False
            return None, False

    def _read_key(self, fd: int) -> Optional[str]:
        ready, _, _ = select.select([fd], [], [], None)
        if not ready:
            return None
        data = os.read(fd, 1)
        if not data:
            return None
        if data == b"\x1b":
            tail = b""
            while True:
                ready, _, _ = select.select([fd], [], [], 0.01)
                if not ready:
                    break
                chunk = os.read(fd, 32)
                if not chunk:
                    break
                tail += chunk
            sequence = data + tail
            mapping = {
                b"\x1b[A": "up",
                b"\x1b[B": "down",
                b"\x1b[C": "right",
                b"\x1b[D": "left",
                b"\x1b[5~": "page_up",
                b"\x1b[6~": "page_down",
            }
            if sequence.startswith(b"\x1b[<"):
                return None
            return mapping.get(sequence, "escape")
        if data in (b"\r", b"\n"):
            return "enter"
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError:
            return None

    def _handle_key(self, key: str) -> bool:
        if key not in ("g",):
            self.pending_g = False
        if key in ("q", "escape"):
            return True
        if key == "g":
            if self.pending_g:
                self._select_edge(first=True)
                self.pending_g = False
            else:
                self.pending_g = True
            return False
        if key == "G":
            self._select_edge(first=False)
            return False
        if key in ("j", "down"):
            self._move_down()
            return False
        if key in ("k", "up"):
            self._move_up()
            return False
        if key in ("h", "left"):
            self._move_left()
            return False
        if key in ("l", "right"):
            self._move_right()
            return False
        if key == "page_up":
            self._move_linear(-(self._terminal_size()[1] - 1))
            return False
        if key == "page_down":
            self._move_linear(self._terminal_size()[1] - 1)
            return False
        if key == "enter":
            self._activate()
            return False
        if key == "+":
            self._deep_expand()
            return False
        if key == "-":
            self._deep_collapse()
            return False
        return False

    def _move_linear(self, delta: int) -> None:
        if not self.view.focus_order:
            return
        try:
            index = self.view.focus_order.index(self.selected_focus)
        except ValueError:
            index = 0
        index = max(0, min(len(self.view.focus_order) - 1, index + delta))
        self.selected_focus = self.view.focus_order[index]

    def _move_down(self) -> None:
        focus = self.selected_focus
        if focus and focus[0] == "table_cell":
            path, row, col = focus[1], focus[2], focus[3]
            rows, cols = self.view.table_shapes.get(path, (0, 0))
            if row + 1 < rows:
                self.selected_focus = ("table_cell", path, row + 1, col)
                return
        self._move_linear(1)

    def _move_up(self) -> None:
        focus = self.selected_focus
        if focus and focus[0] == "table_cell":
            path, row, col = focus[1], focus[2], focus[3]
            if row == 0:
                self.selected_focus = ("table_label", path)
                return
            self.selected_focus = ("table_cell", path, row - 1, col)
            return
        self._move_linear(-1)

    def _move_left(self) -> None:
        focus = self.selected_focus
        if not focus:
            return
        if focus[0] == "hint":
            self.selected_focus = ("tree", focus[1])
            return
        if focus[0] == "table_cell":
            path, row, col = focus[1], focus[2], focus[3]
            if col > 0:
                self.selected_focus = ("table_cell", path, row, col - 1)
            return

    def _move_right(self) -> None:
        focus = self.selected_focus
        if not focus:
            return
        if focus[0] == "tree":
            if ("hint", focus[1]) in self.view.focus_order:
                self.selected_focus = ("hint", focus[1])
            return
        if focus[0] == "table_cell":
            path, row, col = focus[1], focus[2], focus[3]
            rows, cols = self.view.table_shapes.get(path, (0, 0))
            if col + 1 < cols:
                self.selected_focus = ("table_cell", path, row, col + 1)
            return

    def _select_edge(self, first: bool) -> None:
        if not self.view.focus_order:
            return
        self.selected_focus = self.view.focus_order[0 if first else -1]

    def _activate(self) -> None:
        focus = self.selected_focus
        if not focus:
            return
        if focus[0] == "tree":
            path = focus[1]
            node = self._node_at(path)
            if is_container(node):
                if path in self.expanded:
                    self.expanded.remove(path)
                else:
                    self.expanded.add(path)
            return
        if focus[0] == "hint":
            path = focus[1]
            if path in self.table_paths:
                self.table_paths.remove(path)
            else:
                self.table_paths.add(path)
                self.selected_focus = ("table_label", path)
            return
        if focus[0] == "table_label":
            path = focus[1]
            self.table_paths.discard(path)
            if ("hint", path) in self.view.focus_order:
                self.selected_focus = ("hint", path)
            else:
                self.selected_focus = ("tree", path)

    # The original deep expand/collapse walks one visible level at a time.
    def _deep_expand(self) -> None:
        path = self._focus_path(self.selected_focus)
        if path is None:
            return
        node = self._node_at(path)
        if not is_container(node):
            return
        self._expand_step(node, path)

    def _expand_step(self, node: Any, path: tuple) -> bool:
        if not is_container(node):
            return False
        if path not in self.expanded:
            self.expanded.add(path)
            return True
        children = node.items() if isinstance(node, dict) else enumerate(node)
        changed = False
        for key, child in children:
            child_path = path + (key,)
            if is_container(child):
                if child_path not in self.expanded:
                    self.expanded.add(child_path)
                    changed = True
                elif self._expand_step(child, child_path):
                    changed = True
        return changed

    def _deep_collapse(self) -> None:
        path = self._focus_path(self.selected_focus)
        if path is None:
            return
        node = self._node_at(path)
        if not is_container(node):
            return
        self._collapse_step(node, path)

    def _collapse_step(self, node: Any, path: tuple) -> bool:
        if not is_container(node) or path not in self.expanded:
            return False
        children = node.items() if isinstance(node, dict) else enumerate(node)
        for key, child in children:
            child_path = path + (key,)
            if child_path in self.expanded and self._collapse_step(child, child_path):
                return True
        for key, child in children:
            child_path = path + (key,)
            if child_path in self.expanded:
                self.expanded.remove(child_path)
                self.table_paths.discard(child_path)
                return True
        self.expanded.remove(path)
        self.table_paths.discard(path)
        return True

    def _focus_path(self, focus: Optional[tuple]) -> Optional[tuple]:
        if not focus:
            return None
        if focus[0] in ("tree", "hint", "table_label"):
            return focus[1]
        if focus[0] == "table_cell":
            return focus[1]
        return None

    def _node_at(self, path: tuple) -> Any:
        node = self.data
        for part in path:
            node = node[part]
        return node

    def _terminal_size(self) -> tuple[int, int]:
        try:
            size = os.get_terminal_size(sys.stdout.fileno())
            return max(size.columns, 1), max(size.lines, 1)
        except OSError:
            return 80, 24

    def _render_terminal(self) -> None:
        width, height = self._terminal_size()
        self.view = self._build_view(width)
        out = sys.stdout
        if self.fullscreen:
            out.write("\x1b[H\x1b[J")
        else:
            if self.saved_cursor:
                out.write("\x1b[u")
            else:
                out.write("\x1b[s")
                self.saved_cursor = True
            out.write("\x1b[J")
        visual_lines = self._wrap_lines(self.view.lines, width)
        start = min(self.scroll, max(0, len(visual_lines) - 1)) if visual_lines else 0
        selected_line = min(self.view.selected_line, max(0, len(visual_lines) - 1)) if visual_lines else 0
        if selected_line < start:
            start = selected_line
        if selected_line >= start + height:
            start = selected_line - height + 1
        self.scroll = max(0, start)
        visible = visual_lines[self.scroll:self.scroll + height]
        text = "\r\n".join(f"{line}\x1b[K" for line in visible)
        out.write(text)
        out.flush()

    def _render_plain_snapshot(self, width: int) -> str:
        view = self._build_view(width)
        return "\n".join(self._strip_ansi(line) for line in self._wrap_lines(view.lines, width)) + "\n"

    def _strip_ansi(self, text: str) -> str:
        result: list[str] = []
        skip = False
        for char in text:
            if skip:
                if char.isalpha():
                    skip = False
                continue
            if char == "\x1b":
                skip = True
                continue
            result.append(char)
        return "".join(result)

    def _build_view(self, width: int) -> View:
        lines: list[list[Segment]] = []
        focus_order: list[tuple] = []
        table_shapes: dict[tuple, tuple[int, int]] = {}

        def add_line(segments: list[Segment]) -> None:
            lines.append(segments)
            seen = set()
            for segment in segments:
                if segment.focus_id is not None and segment.focus_id not in seen:
                    focus_order.append(segment.focus_id)
                    seen.add(segment.focus_id)

        def prefixed(prefix: str, key: Optional[str]) -> list[Segment]:
            segments = [Segment(prefix)]
            if key is not None:
                segments.append(Segment(json_string(key), BLUE))
                segments.append(Segment(": "))
            return segments

        def render_table(path: tuple, value: list[dict[str, Any]], depth: int, key: Optional[str]) -> None:
            label_focus = ("table_label", path)
            line = prefixed("  " * depth, key)
            line.append(Segment("(array view)", GRAY, label_focus))
            add_line(line)

            columns: list[str] = []
            for row in value:
                for name in row.keys():
                    if name not in columns:
                        columns.append(name)
            rows = len(value)
            cols = len(columns)
            table_shapes[path] = (rows, cols)
            index_width = max(1, len(str(rows - 1)))
            cell_widths = [len(name) for name in columns]
            for row in value:
                for index, name in enumerate(columns):
                    text, _ = summarize(row.get(name, ""))
                    cell_widths[index] = max(cell_widths[index], len(text))

            border_indent = "  " * depth + (" " * index_width)
            add_line([Segment(border_indent + "┏" + "┳".join("━" * width for width in cell_widths) + "┓")])
            header = [Segment("  " * depth), Segment(" " * index_width, GRAY), Segment("┃")]
            for index, name in enumerate(columns):
                header.append(Segment(name.ljust(cell_widths[index])))
                header.append(Segment("┃"))
            add_line(header)
            add_line([Segment(border_indent + "┡" + "╇".join("━" * width for width in cell_widths) + "┩")])
            for row_index, row in enumerate(value):
                row_segments = [Segment("  " * depth), Segment(str(row_index).rjust(index_width), GRAY), Segment("│")]
                for col_index, name in enumerate(columns):
                    raw_value = row.get(name, "")
                    text, style = summarize(raw_value)
                    focus = ("table_cell", path, row_index, col_index)
                    row_segments.append(
                        Segment(text.ljust(cell_widths[col_index]), style, focus)
                    )
                    row_segments.append(Segment("│"))
                add_line(row_segments)
            add_line([Segment(border_indent + "└" + "┴".join("─" * width for width in cell_widths) + "┘")])

        def render_node(value: Any, path: tuple, depth: int, key: Optional[str], is_last: bool, root: bool) -> None:
            if is_eligible_table(value) and path in self.table_paths:
                render_table(path, value, depth, key)
                return

            prefix = "" if root else "  " * depth
            focus = ("tree", path)
            hint_focus = ("hint", path)

            if isinstance(value, dict):
                if path not in self.expanded:
                    line = prefixed(prefix, key)
                    token = "{...}" + ("" if is_last or root else ",")
                    line.append(Segment(token, BOLD, focus))
                    add_line(line)
                    return
                line = prefixed(prefix, key)
                line.append(Segment("{", BOLD, focus))
                add_line(line)
                items = list(value.items())
                for index, (child_key, child) in enumerate(items):
                    render_node(
                        child,
                        path + (child_key,),
                        depth + 1,
                        child_key,
                        index == len(items) - 1,
                        False,
                    )
                close = "}" + ("" if is_last or root else ",")
                add_line([Segment(("  " * depth) + close)])
                return

            if isinstance(value, list):
                hint_needed = is_eligible_table(value)
                if path not in self.expanded:
                    line = prefixed(prefix, key)
                    token = "[...]" + ("" if is_last or root else ",")
                    line.append(Segment(token, BOLD, focus))
                    if hint_needed:
                        line.append(Segment("   "))
                        line.append(Segment("(table view)", GRAY, hint_focus))
                    add_line(line)
                    return
                line = prefixed(prefix, key)
                line.append(Segment("[", BOLD, focus))
                if hint_needed:
                    line.append(Segment("   "))
                    line.append(Segment("(table view)", GRAY, hint_focus))
                add_line(line)
                for index, child in enumerate(value):
                    render_node(
                        child,
                        path + (index,),
                        depth + 1,
                        None,
                        index == len(value) - 1,
                        False,
                    )
                close = "]" + ("" if is_last or root else ",")
                add_line([Segment(("  " * depth) + close)])
                return

            text = format_value(value)
            line = prefixed(prefix, key)
            line.append(Segment(text, primitive_style(value), focus))
            if not is_last and not root:
                line.append(Segment(","))
            add_line(line)

        render_node(self.data, (), 0, None, True, True)
        if focus_order and self.selected_focus not in focus_order:
            self.selected_focus = self._fallback_focus(focus_order)
            return self._build_view(width)

        highlighted = [
            [
                Segment(
                    segment.text,
                    segment.style,
                    segment.focus_id if segment.focus_id != self.selected_focus else ("__selected__",),
                )
                for segment in line
            ]
            for line in lines
        ]
        selected_line = 0
        visual_index = 0
        for line in highlighted:
            found = False
            cursor = 0
            for segment in line:
                length = max(1, len(segment.text))
                if segment.focus_id == ("__selected__",):
                    selected_line = visual_index + (cursor // max(width, 1))
                    found = True
                    break
                cursor += length
            visual_index += max(1, (cursor + max(width, 1) - 1) // max(width, 1))
            if found:
                break
        return View(highlighted, focus_order, table_shapes, selected_line)

    def _fallback_focus(self, focus_order: list[tuple]) -> tuple:
        if not focus_order:
            return ("tree", ())
        path = self._focus_path(self.selected_focus)
        while path is not None:
            for candidate in (("table_label", path), ("hint", path), ("tree", path)):
                if candidate in focus_order:
                    return candidate
            if not path:
                break
            path = path[:-1]
        return focus_order[0]

    def _wrap_lines(self, lines: list[list[Segment]], width: int) -> list[str]:
        width = max(width, 1)
        wrapped: list[str] = []
        for line in lines:
            parts: list[str] = []
            remaining = width
            for segment in line:
                text = segment.text or ""
                while text:
                    if remaining == 0:
                        wrapped.append("".join(parts))
                        parts = []
                        remaining = width
                    take = min(len(text), remaining)
                    piece = text[:take]
                    text = text[take:]
                    selected = segment.focus_id == ("__selected__",)
                    parts.append(style_prefix(segment.style, selected))
                    parts.append(piece)
                    parts.append(style_suffix(segment.style, selected))
                    remaining -= take
                if segment.text == "":
                    selected = segment.focus_id == ("__selected__",)
                    parts.append(style_prefix(segment.style, selected))
                    parts.append(style_suffix(segment.style, selected))
            wrapped.append("".join(parts))
        return wrapped


def parse_args(argv: list[str]) -> tuple[str, Optional[str], bool]:
    help_flag = False
    version_flag = False
    key_flag = False
    fullscreen = False
    invalid = False
    positional: list[str] = []
    stop_options = False

    for arg in argv[1:]:
        if not stop_options and arg == "--":
            stop_options = True
            continue
        if not stop_options and arg in ("-h", "--help"):
            help_flag = True
            continue
        if not stop_options and arg in ("-v", "--version"):
            version_flag = True
            continue
        if not stop_options and arg in ("-k", "--key", "--keybinding"):
            key_flag = True
            continue
        if not stop_options and arg in ("-f", "--fullscreen"):
            fullscreen = True
            continue
        if not stop_options and arg.startswith("-"):
            invalid = True
            continue
        positional.append(arg)

    if invalid:
        return "invalid", None, fullscreen
    if help_flag:
        return "help", None, fullscreen
    if version_flag:
        return "version", None, fullscreen
    if key_flag:
        return "key", None, fullscreen
    if len(positional) > 1:
        return "invalid", None, fullscreen
    return "run", positional[0] if positional else None, fullscreen


def main(argv: list[str]) -> int:
    action, file_path, fullscreen = parse_args(argv)
    if action == "help":
        sys.stdout.write(HELP_TEXT)
        return 0
    if action == "version":
        sys.stdout.write(f"{VERSION}\n")
        return 0
    if action == "key":
        sys.stdout.write(KEYBINDING_TEXT)
        return 0
    if action == "invalid":
        sys.stderr.write("Invalid arguments\n")
        return 1

    try:
        if file_path is None:
            sys.stdout.write("Reading from stdin...")
            sys.stdout.flush()
            raw = sys.stdin.read()
        else:
            with open(file_path, "r", encoding="utf-8") as source:
                raw = source.read()
    except OSError:
        sys.stderr.write(f"Could not open file {file_path}\n")
        return 1

    try:
        data = JsonParser(raw).parse()
    except JsonParseError as exc:
        sys.stderr.write(f"{exc}\n")
        return 1

    return App(data, fullscreen).run()


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
